/** Filter and sorter */
export const FilterAndSorter: Story = {
  name: "Filter and sorter",
  render: () => <Demo5 />,
  parameters: {
    docs: {
      description: { story: "Dùng `filters` để tạo menu lọc trong các cột, `onFilter` để xác định kết quả lọc, `filterMultiple` để cho biết chọn nhiều hay chọn một, `filterOnClose` để chỉ định có kích hoạt lọc khi menu lọc đóng hay không.\n\nDùng `defaultFilteredValue` để một cột được lọc theo mặc định.\n\nDùng `sorter` để cột có thể sắp xếp. `sorter` có thể là một hàm dạng `sorter: function(rowA, rowB) { ... }` để sắp xếp dữ liệu ở local.\n\n`sortDirections: ['ascend', 'descend']` định nghĩa các cách sắp xếp khả dụng cho từng cột, khi đặt trên props của table thì có hiệu lực với mọi cột. Bạn có thể đặt là `['ascend', 'descend', 'ascend']` để sorter không quay về trạng thái mặc định.\n\nDùng `defaultSortOrder` để một cột được sắp xếp theo mặc định.\n\nNếu `sortOrder` hoặc `defaultSortOrder` được chỉ định với giá trị `ascend` hoặc `descend`, bạn có thể truy cập giá trị này bên trong hàm truyền cho `sorter` như đã nêu ở trên. Hàm đó có thể có dạng: `function(a, b, sortOrder) { ... }`." },
      source: { code: Demo5Source, language: 'tsx' },
    },
  },
}

